//! Governed external and generated asset acquisition for AI Studio.
//!
//! Providers return bounded in-memory artifacts into an Editor-owned staging
//! area. Only the existing asset-management import path may copy those bytes
//! into a project or update `asset_manifest.json`.

use crate::agent_host::{
    AgentCapability, AgentHost, AgentHostError, AssetAcquisitionRecord, PermissionCheck,
};
use crate::asset_management::{import_external_asset_files, AssetManagementError};
use engine::AssetManifest;
use engine_authoring::ProjectRoot;
use std::collections::BTreeSet;
use std::fmt;
use std::fs;
use std::io;
use std::path::{Component, Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

const MAX_PROVIDER_ARTIFACTS: usize = 32;
const MAX_PROVIDER_ARTIFACT_BYTES: usize = 32 * 1024 * 1024;
const MAX_ACQUISITION_BYTES: usize = 64 * 1024 * 1024;
const MAX_PROVIDER_SEARCH_RESULTS: usize = 64;
const MAX_METADATA_CHARS: usize = 2_048;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum GeneratedAssetKind {
    Image,
    Audio,
    Model,
    Other,
}

impl GeneratedAssetKind {
    fn label(self) -> &'static str {
        match self {
            Self::Image => "image",
            Self::Audio => "audio",
            Self::Model => "model",
            Self::Other => "other",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AssetSearchRequest {
    pub(crate) query: String,
    pub(crate) limit: usize,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AssetSearchResult {
    pub(crate) provider_asset_id: String,
    pub(crate) title: String,
    pub(crate) source_reference: Option<String>,
    pub(crate) license: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum AssetProviderOperation {
    Acquire {
        provider_asset_id: String,
    },
    Generate {
        kind: GeneratedAssetKind,
        prompt: String,
    },
}

impl AssetProviderOperation {
    fn label(&self) -> &'static str {
        match self {
            Self::Acquire { .. } => "acquire",
            Self::Generate { .. } => "generate",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub(crate) struct AssetProviderRequirements {
    pub(crate) requires_network: bool,
    pub(crate) requires_explicit_user_decision: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub(crate) struct AssetProviderProvenance {
    pub(crate) provider_asset_id: Option<String>,
    pub(crate) source_reference: Option<String>,
    pub(crate) generation_request_id: Option<String>,
    pub(crate) license: Option<String>,
    pub(crate) source_version: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AssetProviderArtifact {
    pub(crate) file_name: String,
    pub(crate) bytes: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AssetProviderOutput {
    pub(crate) artifacts: Vec<AssetProviderArtifact>,
    pub(crate) provenance: AssetProviderProvenance,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ProviderFailureKind {
    Unavailable,
    AuthenticationRequired,
